'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@/components/animate-ui/icons/icon';

type PipetteProps = IconProps<keyof typeof animations>;

const animations = {
  default: {
    body: {
      initial: { rotate: 0, transformOrigin: '19px 5px' },
      animate: {
        rotate: [0, -7, 2, 0],
        transformOrigin: '19px 5px',
        transition: {
          duration: 0.9,
          times: [0, 0.35, 0.7, 1],
          ease: 'easeInOut',
        },
      },
    },
    tip: {
      initial: { pathLength: 1 },
      animate: {
        pathLength: [1, 0, 1],
        transition: { duration: 0.9, times: [0, 0.4, 1], ease: 'easeInOut' },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: PipetteProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      initial="initial"
      animate={controls}
      {...props}
    >
      <motion.path
        d="m12 9-8.414 8.414A2 2 0 0 0 3 18.828v1.344a2 2 0 0 1-.586 1.414A2 2 0 0 1 3.828 21h1.344a2 2 0 0 0 1.414-.586L15 12"
        variants={variants.body}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="m18 9 .4.4a1 1 0 1 1-3 3l-3.8-3.8a1 1 0 1 1 3-3l.4.4 3.4-3.4a1 1 0 1 1 3 3z"
        variants={variants.body}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d="m2 22 .414-.414"
        variants={variants.tip}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function Pipette(props: PipetteProps) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  Pipette,
  Pipette as PipetteIcon,
  type PipetteProps,
  type PipetteProps as PipetteIconProps,
};
